SELECT COALESCE(MAX(step_no), 0)
FROM assistant_agent_step
WHERE agent_task_id = #{agentTaskId}

mapper.update:
UPDATE assistant_agent_step
SET status = 'RUNNING', start_time = COALESCE(start_time, #{startTime}),
    finish_time = NULL, error_code = NULL, error_message = NULL,
    update_time = #{startTime}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE assistant_agent_step
SET status = 'SUCCEEDED', output_summary = #{outputSummary}, output_json = #{outputJson},
    finish_time = #{finishTime}, update_time = #{finishTime}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE assistant_agent_step
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage},
    finish_time = #{finishTime}, update_time = #{finishTime}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE assistant_agent_step
SET status = 'WAITING', update_time = #{updateTime}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE assistant_agent_step
SET status = 'SUCCEEDED', output_summary = #{outputSummary}, output_json = #{outputJson},
    finish_time = #{finishTime}, update_time = #{finishTime}
WHERE id = #{id}
  AND status = 'WAITING'

UPDATE assistant_agent_step
SET status = 'SKIPPED', output_summary = #{outputSummary},
    finish_time = #{finishTime}, update_time = #{finishTime}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE assistant_agent_step
SET status = 'CANCELLED', finish_time = #{finishTime}, update_time = #{finishTime}
WHERE agent_task_id = #{agentTaskId}
  AND status IN ('PENDING', 'RUNNING', 'WAITING')
